select @nam as nam, @tu_ngay as tu_ngay, @den_ngay as den_ngay

exec zrpt_O002_v2 @kieu, @ky, @nam, @tu_ngay, @den_ngay, @nh_kh1, @ma_kh, @ma_ku, @ma_dvcs, '@@sysDatabaseName', @@language, @@userID, @@admin

			
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter; 
			&ScriptQueryFilterString; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	changeLookupReadonly(f, 'ma_dvcs');

	onchangeReportType(f.getItem('kieu'));
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid
			g._hiddenForms = [];
			g._alterTitle = [null, [['%s1', f.getItem('tu_ngay').value, true], ['%s2', f.getItem('den_ngay').value, true]]];
			g._queryFilterString = getQueryFilterString(f, 'tu_ngay, den_ngay, ma_dvcs');
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}
function onchangePeriod(o){
	var f = o.parentForm;
	//if (f.getItemValue('kieu') == '3') f.setItemValue('nam', o.value);
	updateDateFromTo(f);
}
function updateDateFromTo(f) {
	var kieu = f.getItemValue('kieu'), ky = f.getItemValue('ky'), nam = f.getItemValue('nam'), so_ky = f.getItemValue('so_ky')+1
	switch (kieu) {
		case '3': 
			ky = 12;
			so_ky *= 12;
			break;
		case '2':
			so_ky *= 3, ky *= 3;
			break;
		default: break;	
	}
	if (ky > 12 || ky < 0) {
		$message.show(f._language == 'v' ? 'Quý/tháng không hợp lệ' : 'Quarter/month is invalid', String.format('$find(\'{0}\').getItem(\'{1}\').focus();', f._id, 'ky'));
		return;
	}
	var den_ngay = moment(new Date(nam, ky-1, 1)).endOf('month'), tu_ngay  = moment(den_ngay).add(-so_ky+1, 'months').startOf('month')
	f.setItemValue('tu_ngay', tu_ngay._d);
	f.setItemValue('den_ngay', den_ngay._d);
}
function onchangeReportType(o) {
	var f = o.parentForm, ky = f.getItem('ky')//, display = o.value == '3' ? 'none' : ''

	if (o.value == '3') {
		f.setItemValue('ky', '');
		ky.field.AllowNulls = true;
		ky.parentElement.parentElement.style.display = 'none';
	} else {
		//f.setItemValue('ky', '1');
		ky.field.AllowNulls = false;
		ky.parentElement.parentElement.style.display = '';
	}
	onchangePeriod(f.getItem('ky'));
}


		
	

